const src=$input.first();
const f=src.binary?.document||Object.values(src.binary||{})[0];
if(!f)throw new Error('Файл не получен из формы');
const filename=String(f.fileName||'').trim();
const ext=filename.toLowerCase().split('.').pop();
if(!['pdf','docx'].includes(ext))throw new Error('Допустимы только PDF и DOCX');
if(f.fileSize){const s=String(f.fileSize).trim();const n=parseFloat(s);const factor=/gb/i.test(s)?1024*1024*1024:/mb/i.test(s)?1024*1024:/kb/i.test(s)?1024:1;if(Number.isFinite(n)&&n*factor>15*1024*1024)throw new Error('Учебный лимит файла — 15 МБ');}
const m=src.json||{};
const operation=String(m.operation||'').trim();
if(!['Новый','Замена'].includes(operation))throw new Error('Выберите Новый или Замена');
const document_title=String(m.document_title||'').trim();
const version=String(m.version||'').trim();
if(!document_title||!version)throw new Error('Укажите название и версию документа');
// Ключ генерируется автоматически. Для «Замены» название и тип должны совпасть с исходными.
const document_type=String(m.document_type||'Другое').trim();
const normalize=(s)=>s.normalize('NFKC').toLocaleLowerCase('ru-RU').replace(/\s+/g,' ').trim();
const identity=normalize(document_type)+'|'+normalize(document_title);
function fnv32(t,seed){let h=seed>>>0;for(let i=0;i<t.length;i++)h=Math.imul(h^t.charCodeAt(i),16777619);return (h>>>0).toString(16).padStart(8,'0');}
// Две независимые 32-битные контрольные суммы: стабильный внутренний идентификатор, а не ручной ввод.
const document_key='doc-'+fnv32(identity,2166136261)+fnv32(identity,3339675911);
return [{json:{filename,ext,document_key,operation,document_title,version,document_type,effective_date:String(m.effective_date||''),uploaded_at:new Date().toISOString(),file_size:f.fileSize||null},binary:{document:f}}];

const r=$input.first().json||{};
const meta=$('02 · Проверить файл и метаданные').first().json;
let raw=typeof r==='string'?r:String(r.data??r.text??r.body??'');
raw=raw.replace(/\r\n/g,'\n').replace(/\u0000/g,'').trim();
if(raw.length<80)throw new Error('Tika не извлекла достаточно текста: возможен скан без работающего OCR. Проверьте Tesseract и OCR-настройки Tika.');
if(raw.length>300000)throw new Error('Учебный лимит 300000 символов');
const letters=(raw.match(/[\p{L}\p{N}]/gu)||[]).length;
if(letters/raw.length<0.2)throw new Error('Извлечённый текст слишком мало похож на содержательный; нужна ручная проверка OCR');
return [{json:{...meta,raw_text:raw,characters:raw.length,extraction:'Apache Tika; OCR только при настроенном Tesseract',source_page:null}}];

