const m=$('04 · Проверить извлечённый текст').first().json;
const count=Number($input.first().json?.result?.count);
if(!Number.isFinite(count)||count<0)throw new Error('Не удалось получить число фрагментов из Qdrant');
if(m.operation==='Новый'&&count!==0)throw new Error('Документ с таким названием и типом уже существует. Выберите «Замена», если это новая редакция.');
if(m.operation==='Замена'&&count===0)throw new Error('Исходный документ не найден. Для замены укажите ТО ЖЕ название и тип, что при первой загрузке.');
return [{json:{...m,old_chunks:count}}];

const m = $input.first().json;
const raw = m.raw_text;

if (typeof raw !== 'string' || !raw.trim()) {
  throw new Error('Нет текста документа для разбиения');
}

// 1. Создаём постоянные идентификаторы документа и редакции
function fnv(t, seed) {
  let h = seed >>> 0;
  for (let i = 0; i < t.length; i++) {
    h = Math.imul(h ^ t.charCodeAt(i), 16777619);
  }
  return (h >>> 0).toString(16).padStart(8, '0');
}

function uuid(s) {
  const h =
    fnv(s, 2166136261) +
    fnv(s, 3339675911) +
    fnv(s, 987654321) +
    fnv(s, 123456789);

  return `${h.slice(0,8)}-${h.slice(8,12)}-5${h.slice(13,16)}-8${h.slice(17,20)}-${h.slice(20,32)}`;
}

const document_id = uuid(m.document_key);
const revision_id = uuid(
  m.document_key + '|' + raw + '|' +
  m.version + '|' + m.uploaded_at
);

// 2. Настройки размера фрагментов
const SIZE = 1200;
const OVERLAP = 180;

// 3. Ищем пронумерованные пункты в начале строк
// Например: 1. Текст, 2.3. Текст, 2.3.1. Текст
const headingRe = /^[ \t]*(\d+(?:\.\d+){0,5})\.[ \t]+(?=\S)/gm;

const headings = [...raw.matchAll(headingRe)].map(x => ({
  start: x.index,
  number: x[1]
}));

// 4. Разделяем документ по границам найденных пунктов
const sections = [];
let cursor = 0;
let active = null;

for (const h of headings) {
  if (h.start > cursor) {
    sections.push({
      start: cursor,
      end: h.start,
      number: active
    });
  }

  cursor = h.start;
  active = h.number;
}

if (cursor < raw.length) {
  sections.push({
    start: cursor,
    end: raw.length,
    number: active
  });
}

// 5. Собираем фрагменты с номерами пунктов
const chunks = [];
let pending = null;

function addChunk(start, end, numbers) {
  const text = raw.slice(start, end).trim();
  if (!text) return;

  const list = [...new Set(numbers.filter(Boolean))];

  chunks.push({
    text,
    offset_start: start,
    offset_end: end,
    section_number: list.length === 1 ? list[0] : null,
    section_numbers: list
  });
}

function flush() {
  if (pending) {
    addChunk(pending.start, pending.end, pending.numbers);
    pending = null;
  }
}

for (const sec of sections) {
  if (!raw.slice(sec.start, sec.end).trim()) continue;

  const length = sec.end - sec.start;

  // Длинный пункт делим на части
  if (length > SIZE) {
    flush();

    for (let start = sec.start; start < sec.end;) {
      let end = Math.min(start + SIZE, sec.end);

      if (end < sec.end) {
        const tail = raw.slice(
          start + Math.floor(SIZE * 0.65),
          end
        );

        const cut = Math.max(
          tail.lastIndexOf('\n'),
          tail.lastIndexOf(' ')
        );

        if (cut >= 0) {
          end = start + Math.floor(SIZE * 0.65) + cut + 1;
        }
      }

      addChunk(start, end, [sec.number]);

      if (end >= sec.end) break;

      start = Math.max(start + 1, end - OVERLAP);
    }

  // Первый небольшой пункт
  } else if (!pending) {
    pending = {
      start: sec.start,
      end: sec.end,
      numbers: [sec.number]
    };

  // Объединяем соседние небольшие пункты
  } else if (sec.end - pending.start <= SIZE) {
    pending.end = sec.end;
    pending.numbers.push(sec.number);

  // Готовый фрагмент; начинаем следующий
  } else {
    flush();

    pending = {
      start: sec.start,
      end: sec.end,
      numbers: [sec.number]
    };
  }
}

flush();

// 6. Защита от пустого результата и слишком большого документа
if (!chunks.length || chunks.length > 300) {
  throw new Error(
    'Некорректное число чанков: ' + chunks.length
  );
}

// 7. Передаём фрагменты следующей ноде
return chunks.map((c, i) => ({
  json: {
    id: uuid(revision_id + '|' + i + '|' + c.text),

    document_id,
    revision_id,
    document_key: m.document_key,

    operation: m.operation,
    old_chunks: m.old_chunks,

    filename: m.filename,
    document_title: m.document_title,
    document_type: m.document_type,
    version: m.version,
    effective_date: m.effective_date,
    uploaded_at: m.uploaded_at,

    chunk_index: i,
    total_chunks: chunks.length,

    offset_start: c.offset_start,
    offset_end: c.offset_end,

    section_number: c.section_number,
    section_numbers: c.section_numbers,

    text: c.text,
    source_page: null
  }
}));

// Получаем векторы от Ollama
const vectors = $input.item.json.embeddings;

// Получаем исходные фрагменты из текущей группы
const chunks = $('07А · Сгруппировать фрагменты').item.json.chunks;

// Проверяем соответствие количества векторов и фрагментов
if (
  !Array.isArray(vectors) ||
  vectors.length !== chunks.length
) {
  throw new Error(
    `Несовпадение: ${vectors?.length ?? 0} векторов, ${chunks.length} фрагментов`
  );
}

// Создаём точки для Qdrant
const points = chunks.map((s, i) => {
  const vec = vectors[i];

  // E5-small должна возвращать 384 числа
  if (
    !Array.isArray(vec) ||
    vec.length !== 384 ||
    !vec.every(x =>
      typeof x === 'number' && Number.isFinite(x)
    )
  ) {
    throw new Error(
      `Некорректный вектор 384 для фрагмента ${s.chunk_index}`
    );
  }

  return {
    id: s.id,
    vector: vec,
    payload: {
      text: s.text,
      content: s.text,

      document_id: s.document_id,
      document_key: s.document_key,
      revision_id: s.revision_id,

      source: s.filename,
      document_title: s.document_title,
      document_type: s.document_type,
      version: s.version,
      effective_date: s.effective_date,
      uploaded_at: s.uploaded_at,

      chunk_index: s.chunk_index,
      total_chunks: s.total_chunks,
      offset_start: s.offset_start,
      offset_end: s.offset_end,

      // Номера разделов для цитирования
      section_number: s.section_number,
      section_numbers: s.section_numbers,

      page: null
    }
  };
});

// Передаём все точки группы в следующую ноду
return {
  json: {
    points
  }
};

const responses = $input.all();

// Исходные фрагменты документа
const chunks = $('07 · Разбить на фрагменты').all();

// Группы, отправленные в Ollama и Qdrant
const groups = $('07А · Сгруппировать фрагменты').all();

// Проверяем количество ответов Qdrant
if (responses.length !== groups.length) {
  throw new Error(
    `Qdrant вернул ${responses.length} ответов, ожидалось ${groups.length}`
  );
}

// Проверяем подтверждение записи каждой группы
let chunksIndexed = 0;

for (let i = 0; i < responses.length; i++) {
  const response = responses[i].json;

  if (response?.status !== 'ok') {
    throw new Error(
      `Qdrant не подтвердил запись группы № ${i + 1}`
    );
  }

  const groupChunks = groups[i].json?.chunks;

  if (!Array.isArray(groupChunks) || groupChunks.length === 0) {
    throw new Error(
      `Отсутствуют исходные фрагменты группы № ${i + 1}`
    );
  }

  chunksIndexed += groupChunks.length;
}

// Проверяем полноту обработки документа
if (chunksIndexed !== chunks.length) {
  throw new Error(
    `Обработано ${chunksIndexed} фрагментов из ${chunks.length}`
  );
}

const x = chunks[0].json;

// Передаём метаданные следующей ноде
return [{
  json: {
    document_key: x.document_key,
    document_id: x.document_id,
    revision_id: x.revision_id,
    operation: x.operation,
    filename: x.filename,
    document_title: x.document_title,
    version: x.version,
    old_chunks: x.old_chunks,
    chunks_indexed: chunksIndexed
  }
}];

