const m=$('11 · Проверить ответы записи').first().json;
const got=Number($input.first().json?.result?.count);
if(got!==m.chunks_indexed)throw new Error(`Qdrant: новая редакция имеет ${got} точек, ожидалось ${m.chunks_indexed}. Старые не удалены.`);
return [{json:{...m,verified_chunks:got}}];

const m = $('13 · Проверить полноту новой редакции').first().json;

return [{
  json: {
    ok: true,
    operation: m.operation,
    document_key: m.document_key,
    filename: m.filename,
    version: m.version,
    chunks_indexed: m.verified_chunks,
    collection: 'rag_edu_documents_e5_v1',
    message: 'Новый документ успешно проиндексирован'
  }
}];

const m = $('13 · Проверить полноту новой редакции').first().json;

// Получаем ответ Qdrant после удаления старой редакции
const response = $input.first().json;

// Проверяем подтверждение удаления
if (response.status !== 'ok') {
  throw new Error(
    'Qdrant не подтвердил удаление предыдущей редакции документа'
  );
}

// Формируем итоговый результат
return [{
  json: {
    ok: true,
    operation: m.operation,
    document_key: m.document_key,
    filename: m.filename,
    version: m.version,
    chunks_indexed: m.verified_chunks,
    previous_chunks: m.old_chunks,
    collection: 'rag_edu_documents_e5_v1',
    message: 'Новая редакция успешно проиндексирована, предыдущая удалена'
  }
}];

const chunks = $input.all().map(item => item.json);
const batchSize = 5;
const result = [];

for (let i = 0; i < chunks.length; i += batchSize) {
  const batch = chunks.slice(i, i + batchSize);

  result.push({
    json: {
      batch_index: result.length,
      texts: batch.map(chunk => chunk.text),
      chunks: batch
    }
  });
}

return result;
